1	"use client";
2	
3	import { useEffect, useState, type ReactNode } from "react";
4	import {
5	  getHostingAccount,
6	  revealHostingSftpPassword,
7	  recheckHostingHealth,
8	  listHostingSubdomains,
9	  listHostingAddonDomains,
10	  listHostingDatabases,
11	  cancelHostingAccount,
12	  type HostingAccountView,
13	} from "@/lib/actions-hosting";
14	import { Badge, StatusDot } from "@/components/ui/primitives";
15	import { QuotaTile, GettingStarted, TaskFeed, type TaskView } from "./shared";
16	import { AppCredentials } from "./AppCredentials";
17	import { FileManager } from "./FileManager";
18	import { Backups } from "./Backups";
19	import { AppInstaller } from "./AppInstaller";
20	import { DatabasesPanel } from "./DatabasesPanel";
21	import { PhpSwitcher } from "./PhpSwitcher";
22	import { SubdomainsPanel } from "./SubdomainsPanel";
23	import { AddonDomainsPanel } from "./AddonDomainsPanel";
24	import { WebsitesPanel } from "./WebsitesPanel";
25	import { CronPanel } from "./CronPanel";
26	import { EmailTab } from "./EmailTab";
27	import { PlanUpgrade } from "./PlanUpgrade";
28	
29	const TABS = ["Overview", "Websites", "Files", "Databases", "Domains", "Email", "Apps", "Cron", "Backups", "Settings"] as const;
30	
31	export function HostingTabs({ account, initialTab, initialPath }: { account: HostingAccountView; initialTab?: string; initialPath?: string }) {
32	  const keys = TABS.map((t) => t.toLowerCase());
33	  const [tab, setTab] = useState<string>(
34	    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview",
35	  );
36	
37	  const active = account.status === "ACTIVE";
38	
39	  const panels: Record<string, ReactNode> = {
40	    overview: <Overview account={account} />,
41	    websites: active ? <WebsitesPanel accountId={account.id} /> : <NotReady />,
42	    files: active ? <FileManager accountId={account.id} initialPath={initialPath} /> : <NotReady />,
43	    databases: active ? <DatabasesPanel accountId={account.id} username={account.username} maxDatabases={account.maxDatabases} /> : <NotReady />,
44	    domains: active ? <DomainsTab account={account} /> : <NotReady />,
45	    email: active ? <EmailTab account={account} /> : <NotReady />,
46	    apps: active ? <AppsTab account={account} /> : <NotReady />,
47	    cron: active ? <CronPanel accountId={account.id} username={account.username} /> : <NotReady />,
48	    backups: active ? <Backups accountId={account.id} /> : <NotReady />,
49	    settings: <SettingsTab account={account} />,
50	  };
51	
52	  return (
53	    <div>
54	      <div className="mb-6 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md">
55	        {TABS.map((t) => {
56	          const k = t.toLowerCase();
57	          const isActive = tab === k;
58	          return (
59	            <button
60	              key={k}
61	              type="button"
62	              onClick={() => { setTab(k); window.history.replaceState(null, "", `?tab=${k}`); }}
63	              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
64	                isActive
65	                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
66	                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
67	              }`}
68	            >
69	              {t}
70	            </button>
71	          );
72	        })}
73	      </div>
74	      <div className="animate-fade-up">{panels[tab]}</div>
75	    </div>
76	  );
77	}
78	
79	function NotReady() {
80	  return (
81	    <div className="card py-12 text-center">
82	      <h2 className="font-semibold">Still being set up</h2>
83	      <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
84	        This account is provisioning — it usually takes under a minute. This section lights up once it’s active.
85	      </p>
86	    </div>
87	  );
88	}
89	
90	/* ------------------------------------------------------------- Overview --- */
91	
92	function Overview({ account }: { account: HostingAccountView }) {
93	  const [a, setA] = useState(account);
94	  const [sftpPw, setSftpPw] = useState<string | null>(null);
95	  const [tasks, setTasks] = useState<TaskView[]>([]);
96	  const [counts, setCounts] = useState<{ subs: number; addons: number; dbs: number } | null>(null);
97	  const [recheckBusy, setRecheckBusy] = useState(false);
98	
99	  const active = a.status === "ACTIVE";
100	  const diskGB = Math.round(a.diskQuotaMB / 1024);
101	
102	  // "Check now / Go live": flag an immediate recheck, then poll the account for
103	  // ~45s so the stepper reflects the fast-lane result (every ~30s worker tick).
104	  async function recheck() {
105	    setRecheckBusy(true);
106	    const r = await recheckHostingHealth(a.id);
107	    if (r.error) { alert(r.error); setRecheckBusy(false); return; }
108	    let tries = 0;
109	    const poll = setInterval(() => {
110	      tries++;
111	      getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {});
112	      if (tries >= 9) { clearInterval(poll); setRecheckBusy(false); }
113	    }, 5000);
114	  }
115	
116	  // Live-refresh the account (SSL status) until HTTPS is active, so the DNS→HTTPS
117	  // stepper advances on its own.
118	  useEffect(() => {
119	    if (!active || a.sslActive) return;
120	    const t = setInterval(() => { getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {}); }, 15000);
121	    return () => clearInterval(t);
122	  }, [a.id, active, a.sslActive]);
123	
124	  // Counts for the usage meters (extra sites + databases).
125	  useEffect(() => {
126	    if (!active) return;
127	    Promise.all([
128	      listHostingSubdomains(a.id).catch(() => []),
129	      listHostingAddonDomains(a.id).catch(() => []),
130	      listHostingDatabases(a.id).catch(() => []),
131	    ]).then(([subs, addons, dbs]) => setCounts({
132	      subs: subs.filter((s) => s.status !== "DELETING").length,
133	      addons: addons.filter((d) => d.status !== "DELETING").length,
134	      dbs: dbs.length,
135	    }));
136	  }, [a.id, active]);
137	
138	  async function reveal() {
139	    const res = await revealHostingSftpPassword(a.id);
140	    if (res.password) setSftpPw(res.password); else if (res.error) alert(res.error);
141	  }
142	
143	  const extraSites = counts ? counts.subs + counts.addons : 0;
144	
145	  return (
146	    <div className="space-y-6">
147	      {a.status === "FAILED" && (
148	        <div className="card border-red-500/30 text-sm text-red-300">Setup failed{a.error ? `: ${a.error}` : ""}. Contact support or retry from the hosting list.</div>
149	      )}
150	      {(a.status === "PENDING" || a.status === "PROVISIONING") && (
151	        <div className="card border-amber-500/30 text-sm text-amber-200">We’re setting up your account — this usually takes under a minute.</div>
152	      )}
153	
154	      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
155	        {/* Summary */}
156	        <div className="card">
157	          <h2 className="mb-4 font-semibold">Overview</h2>
158	          <dl className="space-y-2.5 text-sm">
159	            <div className="flex items-center justify-between"><dt className="text-slate-400">Status</dt><dd><StatusDot status={a.status} /></dd></div>
160	            <div className="flex items-center justify-between"><dt className="text-slate-400">Plan</dt><dd>{a.planName}</dd></div>
161	            <div className="flex items-center justify-between"><dt className="text-slate-400">PHP version</dt><dd className="font-mono text-xs">{a.phpVersion}</dd></div>
162	            <div className="flex items-center justify-between">
163	              <dt className="text-slate-400">Website</dt>
164	              <dd>
165	                <a href={a.sslActive ? `https://${a.primaryDomain}` : `http://${a.primaryDomain}`} target="_blank" rel="noreferrer" className="text-brand-300 hover:underline">{a.primaryDomain}</a>
166	                {a.sslActive && <Badge tone="green">HTTPS</Badge>}
167	              </dd>
168	            </div>
169	          </dl>
170	        </div>
171	
172	        {/* Free subdomain → already live (wildcard DNS); real domain → point-DNS flow */}
173	        <div className="card">
174	          <div className="mb-4 flex items-center justify-between gap-2">
175	            <h2 className="font-semibold">{a.isFreeSubdomain ? "Your website" : "Point your domain"}</h2>
176	            {active && (
177	              <button
178	                type="button"
179	                className="btn-secondary px-2.5 py-1 text-xs"
180	                disabled={recheckBusy}
181	                onClick={recheck}
182	              >
183	                {recheckBusy ? "Checking…" : a.sslActive ? "Check now" : a.isFreeSubdomain ? "Refresh" : "Go live"}
184	              </button>
185	            )}
186	          </div>
187	          {a.isFreeSubdomain ? (
188	            <p className="text-sm text-slate-400">
189	              Your free subdomain{" "}
190	              <a href={a.sslActive ? `https://${a.primaryDomain}` : `http://${a.primaryDomain}`} target="_blank" rel="noreferrer" className="font-mono text-brand-200 hover:underline">{a.primaryDomain}</a>{" "}
191	              is set up for you automatically — nothing to configure. It goes live the moment provisioning finishes, and a
192	              trusted HTTPS certificate is issued right after. Want a custom domain? Add one anytime from the{" "}
193	              <span className="text-slate-300">Domains</span> tab.
194	            </p>
195	          ) : (
196	            <p className="text-sm text-slate-400">
197	              Create an <span className="font-mono text-slate-200">A</span> record for{" "}
198	              <span className="font-mono text-slate-200">{a.primaryDomain}</span> →{" "}
199	              <span className="font-mono text-brand-200">{a.pointToA}</span>
200	              {a.pointToCname && (<>{" "}(or a <span className="font-mono text-slate-200">CNAME</span> to <span className="font-mono text-slate-200">{a.pointToCname}</span>)</>)}.
201	            </p>
202	          )}
203	          <DnsStepper account={a} />
204	        </div>
205	      </div>
206	
207	      {/* Usage meters */}
208	      {active && (
209	        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
210	          <QuotaTile
211	            label="Storage"
212	            primary={a.diskUsedMB != null ? `${(a.diskUsedMB / 1024).toFixed(a.diskUsedMB < 1024 ? 2 : 1)} of ${diskGB} GB` : `${diskGB} GB SSD`}
213	            bar={a.diskUsedMB != null ? { used: a.diskUsedMB, total: a.diskQuotaMB } : undefined}
214	            note={a.diskUsedMB == null ? "Updates automatically once your site is live" : undefined}
215	          />
216	          <QuotaTile
217	            label="Inodes (files)"
218	            primary={a.inodesUsed != null ? a.inodesUsed.toLocaleString() : "—"}
219	            note={a.inodesUsed == null ? "Measured once your site is live" : "Total files & folders"}
220	          />
221	          <QuotaTile
222	            label="Extra sites"
223	            primary={`${extraSites} of ${a.maxSites}`}
224	            bar={{ used: extraSites, total: a.maxSites }}
225	            note="Subdomains + addon domains (primary is always live)"
226	          />
227	          <QuotaTile
228	            label="Databases"
229	            primary={a.maxDatabases > 0 ? `${counts?.dbs ?? 0} of ${a.maxDatabases}` : "Not on this plan"}
230	            bar={a.maxDatabases > 0 ? { used: counts?.dbs ?? 0, total: a.maxDatabases } : undefined}
231	          />
232	        </div>
233	      )}
234	
235	      {/* SFTP access */}
236	      {active && (
237	        <div className="flex flex-wrap items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
238	          <span className="font-medium text-slate-300">SFTP</span>
239	          <span className="text-slate-400"><span className="font-mono text-slate-200">{a.username}</span>@{a.pointToA}</span>
240	          {sftpPw ? (
241	            <span className="font-mono text-brand-200">{sftpPw}</span>
242	          ) : (
243	            <button className="text-xs text-brand-300 hover:underline" onClick={reveal}>show password</button>
244	          )}
245	        </div>
246	      )}
247	
248	      {/* Getting started + task progress */}
249	      {active && <AppCredentials accountId={a.id} />}
250	      {active && <GettingStarted accountId={a.id} freeSubdomain={a.isFreeSubdomain} primaryDomain={a.primaryDomain} />}
251	      <TaskFeed accountId={a.id} active={active} onTasks={setTasks} />
252	      {/* tasks kept for the feed; referenced to avoid an unused-setter lint */}
253	      <span className="hidden">{tasks.length}</span>
254	    </div>
255	  );
256	}
257	
258	/**
259	 * DNS→HTTPS stepper driven by the REAL serve-verification the worker records
260	 * (serveHttpOk / serveHttpsOk / sslActive), so it can never claim "live" while
261	 * HTTPS actually refuses. Three overall states, per the account's measured health:
262	 *   • verified — a trusted cert is live (sslActive) and 443 answers → "HTTPS live ✓"
263	 *   • issuing  — the site answers (self-signed 443 or HTTP) but no trusted cert yet
264	 *   • dns      — nothing answers for the domain yet (DNS not pointed at us)
265	 */
266	function DnsStepper({ account }: { account: HostingAccountView }) {
267	  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
268	  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
269	  const verified = account.sslActive && account.serveHttpsOk !== false;
270	  const state: "verified" | "issuing" | "dns" | "pending" =
271	    verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
272	
273	  const free = account.isFreeSubdomain;
274	  const steps = [
275	    { label: free ? "DNS ready" : "Point domain", done: true, hint: free ? "Set up automatically" : "Add the A record above" },
276	    {
277	      label: "Site live",
278	      done: state === "issuing" || state === "verified",
279	      hint: state === "issuing" || state === "verified" ? "Serving traffic" : state === "dns" ? "DNS not detected yet" : "Checking…",
280	    },
281	    {
282	      label: "HTTPS verified",
283	      done: state === "verified",
284	      hint: state === "verified" ? "Certificate trusted" : state === "issuing" ? "Issuing certificate" : "Auto after DNS",
285	    },
286	  ];
287	
288	  const headline =
289	    account.healthNote ??
290	    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
291	  const headlineTone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
292	
293	  return (
294	    <div className="mt-4">
295	      <div className="flex items-center">
296	        {steps.map((s, i) => (
297	          <div key={s.label} className="flex flex-1 items-center last:flex-none">
298	            <div className="flex flex-col items-center">
299	              <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
300	                {s.done ? "✓" : i + 1}
301	              </span>
302	            </div>
303	            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
304	          </div>
305	        ))}
306	      </div>
307	      <div className="mt-1.5 flex items-start justify-between text-[11px]">
308	        {steps.map((s) => (
309	          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
310	            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
311	            <p className="text-slate-500">{s.hint}</p>
312	          </div>
313	        ))}
314	      </div>
315	      <p className={`mt-3 text-xs font-medium ${headlineTone}`}>
316	        {headline}
317	        {account.healthCheckedAt && (
318	          <span className="ml-1 font-normal text-slate-500">· checked {new Date(account.healthCheckedAt).toLocaleTimeString()}</span>
319	        )}
320	      </p>
321	      {state !== "verified" && (
322	        <p className="mt-1 text-xs text-slate-500">
323	          {free ? (
324	            <>A trusted HTTPS certificate is issued automatically once provisioning completes — this usually takes a minute. Use <span className="text-slate-300">Refresh</span> to check right away.</>
325	          ) : (
326	            <>A trusted HTTPS certificate is issued automatically once your domain resolves to us — this can take a few minutes after you set the DNS record. Use <span className="text-slate-300">Go live</span> to check right away.</>
327	          )}
328	        </p>
329	      )}
330	    </div>
331	  );
332	}
333	
334	/* -------------------------------------------------------------- Domains --- */
335	
336	function DomainsTab({ account }: { account: HostingAccountView }) {
337	  return (
338	    <div className="space-y-6">
339	      <div className="card">
340	        <h3 className="mb-1 font-semibold">Primary domain</h3>
341	        <div className="flex flex-wrap items-center gap-2 text-sm">
342	          <a href={account.sslActive ? `https://${account.primaryDomain}` : `http://${account.primaryDomain}`} target="_blank" rel="noreferrer" className="font-mono text-slate-200 hover:underline">{account.primaryDomain}</a>
343	          <StatusDot status={account.status} />
344	          {account.sslActive ? <Badge tone="green">HTTPS</Badge> : <Badge tone="amber">HTTP</Badge>}
345	        </div>
346	        <p className="mt-2 text-xs text-slate-500">
347	          Your account’s main website, served from <span className="font-mono text-slate-400">public_html</span>.
348	          {account.isFreeSubdomain ? (
349	            <> This is a free Nxeon subdomain — DNS and HTTPS are handled for you, nothing to point. Add your own domain below whenever you’re ready.</>
350	          ) : (
351	            <> Point its A record to <span className="font-mono text-brand-300">{account.pointToA}</span>.</>
352	          )}
353	        </p>
354	      </div>
355	      <SubdomainsPanel accountId={account.id} primaryDomain={account.primaryDomain} pointToA={account.pointToA} />
356	      <AddonDomainsPanel accountId={account.id} pointToA={account.pointToA} />
357	    </div>
358	  );
