420	/**
421	 * Self-serve hosting cancel. Destructive + irreversible, so it demands a strong
422	 * two-step confirmation: the customer must type the account's primary domain
423	 * exactly before the final "Cancel account" button unlocks. On success the account
424	 * flips to DELETING and the provisioner tears it down; we send the customer back to
425	 * the hosting list.
426	 */
427	function CancelHostingAccount({ accountId, primaryDomain }: { accountId: string; primaryDomain: string }) {
428	  const [open, setOpen] = useState(false);
429	  const [confirmText, setConfirmText] = useState("");
430	  const [busy, setBusy] = useState(false);
431	  const [error, setError] = useState<string | null>(null);
432	
433	  const matches = confirmText.trim().toLowerCase() === primaryDomain.trim().toLowerCase();
434	
435	  function close() {
436	    if (busy) return;
437	    setOpen(false);
438	    setConfirmText("");
439	    setError(null);
440	  }
441	
442	  async function submit() {
443	    if (!matches || busy) return;
444	    setBusy(true);
445	    setError(null);
446	    const res = await cancelHostingAccount(accountId);
447	    if (res.error) {
448	      setError(res.error);
449	      setBusy(false);
450	      return;
451	    }
452	    // Account is now DELETING — leave this page for the hosting list.
453	    window.location.href = "/dashboard/hosting";
454	  }
455	
456	  return (
457	    <>
458	      <button type="button" className="btn-secondary border-red-500/40 px-3 py-1.5 text-sm text-red-300 hover:bg-red-500/10" onClick={() => setOpen(true)}>
459	        Cancel hosting account
460	      </button>
461	
462	      {open && (
463	        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm" onClick={close}>
464	          <div className="w-full max-w-md rounded-2xl border border-red-500/30 bg-navy-900 p-6 shadow-2xl" onClick={(e) => e.stopPropagation()}>
465	            <h3 className="font-semibold text-red-300">Cancel hosting account</h3>
466	            <p className="mt-2 text-sm text-slate-400">
467	              This permanently removes <span className="font-mono text-slate-200">{primaryDomain}</span> — its files,
468	              databases and sites. <span className="text-red-300">This can’t be undone and there is no backup afterwards.</span>
469	            </p>
470	            <label className="mt-4 block text-xs text-slate-400">
471	              Type <span className="font-mono text-slate-200">{primaryDomain}</span> to confirm
472	            </label>
