function MailboxItem({ mailbox }: { mailbox: MailboxRow }) {
  const [pending, start] = useTransition();
  const [pwPending, startPw] = useTransition();
  const [retryPending, startRetry] = useTransition();
  const [error, setError] = useState<string | null>(null);
  // A success-with-a-caveat, distinct from an error: e.g. removed from the account
  // while the mail server was unreachable, so the mailbox itself may still exist.
  // Red would read as failure; nothing would hide a fact the customer needs.
  const [notice, setNotice] = useState<string | null>(null);
  const [password, setPassword] = useState<string | null>(null);
  const [pwNote, setPwNote] = useState<string | null>(null);
  const [status, setStatus] = useState(mailbox.status);

  const badge = statusBadge(status);
  // Only a live mailbox can actually be signed in to. Offering "Open inbox" on a
  // FAILED row would send the customer to a webmail error page instead of
  // telling them the mailbox was never created on the mail server.
  const usable = status === "ACTIVE";
  const retryable = status === "FAILED" || status === "PROVISIONING";

  function retry() {
    setError(null);
    setPwNote(null);
    startRetry(async () => {
      const res = await retryMailboxProvision(mailbox.id);
      if (res?.error) {
        setError(res.error);
        setStatus("FAILED");
      } else if (res?.ok) {
        setStatus("ACTIVE");
        setPwNote("Mailbox created on the mail server. Use Show password to sign in.");
      }
    });
  }

  function reveal() {
    setError(null);
    setPwNote(null);
    startPw(async () => {
      const res = await revealMailboxPassword(mailbox.id);
      if (res?.error) setError(res.error);
      else if (res?.password) {
        setPassword(res.password);
        setPwNote("Current password — sign in with your full mailbox address.");
      }
    });
  }

  function resetPw() {
    if (!confirm(`Reset the password for ${mailbox.address}? The current password will stop working.`)) return;
    setError(null);
    setPwNote(null);
    startPw(async () => {
      const res = await resetMailboxPassword(mailbox.id);
      if (res?.error) setError(res.error);
      else if (res?.password) {
        setPassword(res.password);
        setPwNote("New password set — copy it now, it won't be shown again automatically.");
      }
    });
  }

  return (
    <div className="rounded-lg border border-white/[0.06] px-3 py-2">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <span className="font-mono text-sm text-white">{mailbox.address}</span>
          <Badge tone={badge.tone}>{badge.label}</Badge>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {/* Per-mailbox action. The panel previously offered one generic
              "Open inbox →" for the whole account, which always landed on the
              oldest mailbox — so a customer with several boxes had no way to
              open the one they were looking at. `?mailbox=` is validated
              server-side against the mailboxes this user owns. */}
          {usable && (
            <Link
              href={`/dashboard/mail?mailbox=${encodeURIComponent(mailbox.address)}`}
              className="btn-secondary py-1 text-xs"
            >
              Open inbox →
            </Link>
          )}
          {retryable && (
            <button className="btn-secondary py-1 text-xs" disabled={retryPending} onClick={retry}>
              {retryPending ? "Retrying…" : "Retry setup"}
            </button>
          )}
          <RowMenu
            label={`More actions for ${mailbox.address}`}
            items={[
              {
                label: pwPending ? "…" : password ? "Refresh password" : "Show password",
                onClick: reveal,
                disabled: pwPending,
              },
              { label: "Reset password", onClick: resetPw, disabled: pwPending },
              {
                label: "Remove",
                danger: true,
                disabled: pending,
                onClick: () => {
                  if (!confirm(`Remove mailbox ${mailbox.address}?`)) return;
                  setError(null);
                  start(async () => {
                    setError(null);
                    setNotice(null);
                    const res = await removeMailbox(mailbox.id);
                    if (res?.error) setError(res.error);
                    else if (res?.warning) setNotice(res.warning);
                  });
