          />
        </div>
      </div>

      {error && <p className="mt-2 text-xs text-red-400">{error}</p>}
      {notice && <p className="mt-2 text-xs text-amber-400">{notice}</p>}

      {/* Say what a non-ACTIVE status MEANS for their mail. A bare badge leaves
          the customer to guess whether mail is arriving. */}
      {status === "FAILED" && (
        <p className="mt-2 text-xs text-red-400">
          This mailbox was never created on the mail server, so mail sent to it is being rejected. Press
          Retry setup — if it fails again, open a ticket.
        </p>
      )}
      {status === "PROVISIONING" && (
        <p className="mt-2 text-xs text-amber-400">
          Waiting on the mail server. Mail to this address won&apos;t be delivered until it goes active.
        </p>
      )}
      {status === "SUSPENDED" && (
        <p className="mt-2 text-xs text-slate-400">
          Sign-in is disabled for this mailbox. Existing mail is kept.
        </p>
      )}

